int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> reach(n + 1, vector<int>(n + 1, 0));

    for (int i = 1; i <= n; ++i) reach[i][i] = 1;

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        reach[a][b] = 1;
        reach[b][a] = 1;
    }

    // Floyd-Warshall for transitive closure
    for (int k = 1; k <= n; ++k) {
        for (int i = 1; i <= n; ++i) {
            if (!reach[i][k]) continue;
            for (int j = 1; j <= n; ++j) {
                if (reach[k][j]) reach[i][j] = 1;
            }
        }
    }

    int q;
    cin >> q;
    while (q--) {
        int a, b;
        cin >> a >> b;
        cout << (reach[a][b] ? "YES" : "NO") << '\n';
    }

    return 0;
}

