#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int to;
    int next;
} Edge;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *head = (int *)malloc((N + 1) * sizeof(int));
    Edge *edges = (Edge *)malloc((2 * M) * sizeof(Edge));
    if (!head || !edges) return 0;

    for (int i = 1; i <= N; i++) head[i] = -1;

    int edgeCount = 0;
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        edges[edgeCount].to = b;
        edges[edgeCount].next = head[a];
        head[a] = edgeCount++;

        edges[edgeCount].to = a;
        edges[edgeCount].next = head[b];
        head[b] = edgeCount++;
    }

    int *component = (int *)calloc(N + 1, sizeof(int));
    int *queue = (int *)malloc((N + 1) * sizeof(int));
    if (!component || !queue) return 0;

    int compId = 0;

    for (int i = 1; i <= N; i++) {
        if (component[i] != 0) continue;

        compId++;
        int front = 0, back = 0;
        queue[back++] = i;
        component[i] = compId;

        while (front < back) {
            int u = queue[front++];
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (component[v] == 0) {
                    component[v] = compId;
                    queue[back++] = v;
                }
            }
        }
    }

    int Q;
    scanf("%d", &Q);
    while (Q--) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (component[u] == component[v]) {
            printf("YES\n");
        } else {
            printf("NO\n");
        }
    }

    free(head);
    free(edges);
    free(component);
    free(queue);
    return 0;
}

